SELECT

FROM agents
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL

SELECT

FROM agent_versions
WHERE workspace_uuid = #{workspaceUUID}
AND agent_external_id = #{externalID}
