SELECT

FROM agents
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
FOR UPDATE

SELECT

FROM agents

    workspace_uuid = #{filter.WorkspaceUUID}
    AND deleted_at IS NULL

        AND archived_at IS NULL


        AND created_at >= #{filter.CreatedAtGTE}


        AND created_at <= #{filter.CreatedAtLTE}


        AND POSITION(LOWER(#{filter.Name}) IN LOWER(name)) > 0


        AND (created_at, uuid) < (#{filter.Cursor.CreatedAt}, #{filter.Cursor.UUID})


ORDER BY created_at DESC, uuid DESC
LIMIT #{filter.Limit}

SELECT uuid
FROM agents
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL

SELECT

FROM agent_versions

    agent_uuid = #{agentUUID}

        AND (version, uuid) < (#{cursor.Version}, #{cursor.UUID})


ORDER BY version DESC, uuid DESC
LIMIT #{limit}
